from h34 import *
M=mcq;F=tf;S=short;N=num
chapter(3,'evs','going-to-the-mela','Going to the Mela',
 ('Nita and Radha get ready','A mela has come to town, and Nita and Radha are very excited. They invite Dadiji, who is not sure because her legs hurt. Their neighbours Sneha and Rohit and their uncle Mohan Chacha\'s family come too. Together they plan the trip, travel by bus, enjoy the mela and learn how to stay safe.'),
 [('Getting ready for a trip',['Before they leave, Nita and Radha fill their water bottles and pack a special bag. We should also prepare for a trip by taking water, a bag and anything we need.','Nita\'s father reminds the neighbours to be ready on time. Being on time helps everyone travel together.','Mohan Chacha and his family come by train, then take a city bus and an autorickshaw to reach the mela ground. People can use different kinds of transport to reach the same place.']),
  ('Travelling safely',['Nita holds Dadiji\'s hand and leads her slowly to the bus stop. They walk carefully and keep an eye on the vehicles on both sides of the road.','Bus number 401 stops and the conductor and Nita\'s father help Dadiji get in. There is a seat reserved for older people.','Rohit\'s father buys five full tickets and four half tickets for the group. He asks the children to sit on their seats and not to put their hands or heads out of the window.','We should help older people, sit properly on a bus and stay safe.']),
  ('At the mela',['At the entrance there is a map of the mela ground showing the stalls. An ambulance, a police jeep and a fire engine are parked nearby, and there is a Lost and Found booth with volunteers.','Mohan Chacha and Rohit get a wheelchair for Dadiji so she can move around comfortably.','Fire engines and ambulances are present to help quickly if there is a fire or if someone is hurt. The Lost and Found booth helps people find lost things and lost children.','The children enjoy the toy stall, where they buy spinning tops, puppets, phirkis and dolls. They ride the merry-go-round and the giant wheel, and Sneha and Radha buy bangles.','They watch a magic show and then wash their hands at the water point before they eat gol gappas, chaat, chhole kulche, jalebis with rabri and kulfi.','After eating, they put the waste in the dustbin so the ground stays clean.']),
  ('Helpers and safety at a fair',['A police officer and a police dog are at the mela. The police help to keep everyone safe, and the dog helps to find things and keep order.','If we get lost in a crowd, we should stay where we are and go to a police officer or the Lost and Found booth, not walk away with a stranger.','The Kumbh Mela is the biggest festival in the world. It is held every 12 years at Haridwar, Prayagraj, Nashik and Ujjain, on the banks of rivers such as the Ganga, Yamuna, Godavari and Shipra.','A sketch or map helps us find places. We can circle our house, the school and the places on the route to find the shortest way.'])],
 [('Why do melas keep an ambulance and a fire engine at the entrance?',[('Many people gather in one place.','Crowds can lead to accidents.'),('If someone is hurt or a fire starts, help is needed quickly.','The ambulance helps the hurt person and the fire engine puts out a fire.'),('So they stay near the entrance to be ready.','Being prepared keeps everyone safe.')]),
  ('A child loses sight of the family in a crowded mela. What should the child do?',[('Stay calm and do not run around.','Moving away makes it harder to be found.'),('Go to a police officer or the Lost and Found booth.','They are there to help.'),('Tell them your name and your family\'s names.','They will call out and find your family.')])],
 ('Describe how Nita\'s family got ready and reached the mela.',['Water bottles and a bag','Walked carefully to the bus stop','Helped Dadiji onto the bus','Bought tickets and sat safely'],['They took a train from home','Dadiji stayed behind']),
 ['We prepare for a trip with water, a bag and being on time.','We help older people and keep safe on the road and in a bus.','A mela has stalls, games, food, helpers and safety booths.','We wash our hands before eating and use the dustbin.','If we are lost, we go to a police officer or the Lost and Found booth.'],
 [M('1',1,'How did Nita\'s family reach the mela?','By bus',[('By train','Mohan Chacha came by train'),('On foot all the way','They took bus number 401')],'They went by bus.'),
  M('2',1,'Who sat on a seat reserved for older people?','Dadiji',[('Rohit','Rohit is a child'),('Nita','Nita is a child')],'Dadiji sat on the reserved seat.'),
  M('3',1,'What is the Lost and Found booth for?','Helping find lost things and people',[('Selling toys','The toy stall sells toys'),('Giving rides','Rides are elsewhere')],'It helps find lost things and children.'),
  M('4',1,'Why did the children wash their hands before eating?','To remove germs',[('To make them wet','Washing is for health'),('Because they were hot','Washing removes germs')],'Clean hands keep us healthy.'),
  M('5',2,'What did the children do with waste after eating?','Put it in the dustbin',[('Threw it on the ground','That makes the ground dirty'),('Took it home','They used the dustbin')],'They kept the mela clean.'),
  M('6',2,'Why were an ambulance and a fire engine parked near the entrance?','To help quickly in an emergency',[('To give rides','They are not for rides'),('To sell food','They are not for selling')],'They help in an emergency.'),
  F('7',2,'A child lost in a crowd should walk far away to look for the family.',False,'Staying near and asking the police or the Lost and Found booth is safer.'),
  M('8',2,'Which is a safe way to sit in a bus?','Stay on the seat and keep hands inside',[('Put your head out of the window','That is dangerous'),('Jump around','You could fall')],'We must sit properly.'),
  M('9',2,'Who accompanied the police officer?','A police dog',[('A horse','The story says a dog'),('A cat','The story says a dog')],'The police dog helps keep order.'),
  S('10',2,'What do we use to find places in a mela ground?',['map','a map','sketch'],'A map or sketch shows the stalls.'),
  M('11',3,'How often is the Kumbh Mela held at each place?','Once every 12 years',[('Every year','It is much less often'),('Every month','It is much less often')],'It is held once every 12 years.'),
  F('12',3,'We should help older people when we travel.',True,'Helping elders is kind.')],
 keep=['mela','bus','map'])
